INSERT INTO public.news_company_links (news_id, company_id, news_hash, company_hash, active, match_method, match_score, match_reasons, topics, importance, importance_status, importance_reason, importance_evidence, importance_method, importance_attempts, analysis_status, analysis_run_id, analysis_result, analysis_as_of, error_code, matched_at, updated_at) VALUES ('6fd817b6b18a3c411d8fd211415892665b9b818b72cc3d64c13f61fe937b10b7', 'U_125887', '1ce56804b716826d2e9fa0d93af90832adacb7c11ae2df4a81f93b1afe6b1b09', '3dffbda6323de71ae64a73cafb595d71b5f6941b16fc9d4edb9e57f00eaa8093', true, 'hybrid', 0.09677419, '[{"kind": "industry", "okved": "45.31", "query": "Автозапчасти, спрос на автомобили, автокредитование и автолизинг", "lexical_query": "\"автозапчасти\" OR \"автокомпоненты\" OR \"автомобили\" OR \"автокредитование\" OR \"автолизинг\""}]', '["automotive", "regulation"]', 'medium', 'ready', 'Минпромторг планирует увеличить финансирование программ льготного автокредитования и лизинга. Это может косвенно стимулировать спрос на автомобили и запчасти, что важно для компании, занимающейся оптовой торговлей автодеталями.', '[{"quote": "предложит варианты увеличения финансирования программ льготного автокредитования и автолизинга.", "source_id": "news:6fd817b6b18a3c411d8fd211415892665b9b818b72cc3d64c13f61fe937b10b7"}, {"quote": "[\"45.31\"]", "source_id": "company:U_125887:okved_codes"}]', 'triage', 0, 'pending', NULL, NULL, NULL, NULL, '2026-10-23 17:26:13.284367+00', '2026-10-23 18:06:36.826387+00') ON CONFLICT DO NOTHING;
INSERT INTO public.news_company_links (news_id, company_id, news_hash, company_hash, active, match_method, match_score, match_reasons, topics, importance, importance_status, importance_reason, importance_evidence, importance_method, importance_attempts, analysis_status, analysis_run_id, analysis_result, analysis_as_of, error_code, matched_at, updated_at) VALUES ('9bfb602e317f62a40ab4bd588e14178869a9ee317e02572c6083315e6f4fd66c', 'U_123091', 'a15e983f3a179662b0693c06561d9a81741499b3d42707108226083a234d93e1', 'd5765a6345e4b864fd4feae5a1a645d764c36472386e5dfbacf3ae4f44ad8b8c', true, 'hybrid', 0.09677419, '[{"kind": "financing", "query": "Решения и прогнозы ЦБ по ключевой ставке, стоимость кредитования", "lexical_query": "\"ключевая ставка\" OR \"ставка ЦБ\""}]', '["financial_markets", "regulation"]', 'medium', 'ready', 'Решение ЦБ РФ по ключевой ставке косвенно влияет на компанию через стоимость обслуживания кредитов (указан в banking_services) и общую экономическую активность. Прогнозы аналитиков о сохранении высокой ставки до конца 2026 года могут означать длительное сохранение высоких затрат на заемный капитал.', '[{"quote": "INTERFAX.RU - Аналитики единогласно прогнозируют сохранение ключевой ставки ЦБ РФ в ближайшую пятницу на уровне 14%.", "source_id": "news:9bfb602e317f62a40ab4bd588e14178869a9ee317e02572c6083315e6f4fd66c"}, {"quote": "[\"45.31.1\"]", "source_id": "company:U_123091:okved_codes"}]', 'triage', 0, 'pending', NULL, NULL, NULL, NULL, '2026-10-23 17:26:13.299169+00', '2026-10-23 18:06:36.660393+00') ON CONFLICT DO NOTHING;
INSERT INTO public.news_company_links (news_id, company_id, news_hash, company_hash, active, match_method, match_score, match_reasons, topics, importance, importance_status, importance_reason, importance_evidence, importance_method, importance_attempts, analysis_status, analysis_run_id, analysis_result, analysis_as_of, error_code, matched_at, updated_at) VALUES ('9bfb602e317f62a40ab4bd588e14178869a9ee317e02572c6083315e6f4fd66c', 'U_128194', 'a15e983f3a179662b0693c06561d9a81741499b3d42707108226083a234d93e1', '8acd4495d1663cd05112f99ff359a881362f97810afaa5656c6f6b87820cb752', true, 'hybrid', 0.09677419, '[{"kind": "financing", "query": "Решения и прогнозы ЦБ по ключевой ставке, стоимость кредитования", "lexical_query": "\"ключевая ставка\" OR \"ставка ЦБ\""}]', '["financial_markets", "regulation"]', 'medium', 'ready', 'Решение ЦБ РФ по ключевой ставке косвенно влияет на компанию через стоимость обслуживания кредитов и условия финансирования, так как компания пользуется банковскими услугами (credit). Прогнозы аналитиков о сохранении высокой ставки на длительный срок могут увеличить финансовую нагрузку.', '[{"quote": "INTERFAX.RU - Аналитики единогласно прогнозируют сохранение ключевой ставки ЦБ РФ в ближайшую пятницу на уровне 14%.", "source_id": "news:9bfb602e317f62a40ab4bd588e14178869a9ee317e02572c6083315e6f4fd66c"}, {"quote": "[\"cash_register\", \"credit\", \"payroll\"]", "source_id": "company:U_128194:banking_services"}]', 'triage', 0, 'partial', NULL, '{"mode": "live", "as_of": "2026-10-22T13:45:06.870942+00:00", "event": {"id": "9bfb602e317f62a40ab4bd588e14178869a9ee317e02572c6083315e6f4fd66c", "url": "https://www.interfax.ru/business/1124070", "text": "Москва. 21 октября. INTERFAX.RU - Аналитики единогласно прогнозируют сохранение ключевой ставки ЦБ РФ в ближайшую пятницу на уровне 14%. Эксперты расходятся только в оценке тона сигнала: останется он нейтральным или будет ужесточен.\n\nБанк России на заседании 11 сентября принял решение оставить ключевую ставку на уровне 14% после десяти снижений подряд. Регулятор тогда сохранил нейтральный сигнал: \"Банк России будет принимать дальнейшие решения по ключевой ставке в зависимости от динамики инфляции и инфляционных ожиданий, а также от оценки рисков со стороны внутренних и внешних условий\".\n\nЦБ не давал новых сигналов перед октябрьским заседанием. Решение будет приниматься исходя из поступающих данных, заявил на прошлой неделе зампред Банка России Алексей Заботкин. При этом он подчеркнул, что на опорном заседании в октябре будет уточнено влияние выбытия мощностей в разных отраслях экономики на прогноз 2026-2027 годов. Также регулятор учтет в прогнозе тот факт, что инфляция в РФ в III квартале оказалась немного выше ожиданий, добавил Заботкин.\n\nГодовая инфляция на 19 октября замедлилась до 7,15% с 7,22% на 12 октября (на конец сентября составляла 6,35%), если ее определять из среднесуточных данных за весь октябрь 2025 года (так показатель рассчитывает Минэкономразвития) и до 6,84% с 7,02% на 12 октября, если ее высчитывать из недельной динамики (такой методики обычно придерживается ЦБ).\n\nБанк России в преддверии заседания опубликовал свежие данные по инфляционным ожиданиям населения, в октябре они упали с 14,2% до 13,2%, приблизившись к февральскому уровню (13,1%). Ценовые ожидания бизнеса в октябре снизились после роста с июля, но остаются выше уровне II квартала 2026 года, отмечал ранее Банк России.\n\nРешение сохранить ставку и нейтральный сигнал на октябрьском заседании регулятор может объяснить ускорением инфляции в III квартале из-за частичного выпадения производственного потенциала экономики, считают аналитики SberCIB Investment Research. \"ЦБ потребуется время, чтобы удостовериться в том, что произошедшее сокращение предложения носит временный характер и что нет признаков разгона инфляционных ожиданий. С другой стороны, регулятор отметит сохранение пространства для снижения ставки в 2027 году, поскольку заявленные Минфином параметры бюджета на ближайшую трехлетку соответствовали более ранним прогнозам ЦБ\", - отмечают эксперты.\n\nВ пользу неизменности ключевой ставки говорит сохранение устойчивого роста цен и инфляционных ожиданий на повышенном уровне, ограничение возможности расширения предложения из-за выбытия части производственных и логистических мощностей, поддержание совокупного спроса в экономике смягчившимися денежно-кредитными условиями, отмечают экономисты \"Ренессанс Капитала\". Они ждут, что Банк России повысит прогноз по инфляции на 2026 год с 6-7% до 6,5-7,5%, на 2027 год - с 4% до 4-4,5%. Прогноз по средней ключевой ставке на 2027 год может быть повышен с 10,5-12,5% до 11,5-13,5%. \"Возможность для возобновления цикла снижения ключевой ставки может представиться уже на рубеже нового года, если ситуация на топливном рынке продолжит нормализовываться, \"устойчивые\" темпы роста цен - замедляться, а реакция инфляционных ожиданий на повышенную индексацию коммунальных тарифов будет ограниченной\", - подчеркивают эксперты.\n\nНе позволяет снизить ставку повышение инфляции в стабильных компонентах, рост кредита и денежной массы выше прогнозов регулятора, отмечают аналитики ИБ \"Синара\". Наряду с неизменной ставкой в октябре, они ждут умеренно жесткого сигнала. \"Более того, существующие риски заставляют предположить, что ставка останется на уровне 14% до конца года\", - считают эксперты. Главным событием, по их мнению, станет не решение по ставке, а пересмотр среднесрочного прогноза. Экономисты также прогнозируют повышение прогноза по инфляции на 2026 год до 6,5-7,5%, на 2027 год - до 4,5-5%. Диапазон средней ключевой ставки на 2027 год, по их мнению, будет повышен с 10,5-12,5% до 12-14%.\n\nЭкономисты Газпромбанка также ждут сохранения ставки на уровне 14% в октябре и декабре из-за того, что инфляция складывается заметно выше ориентиров регулятора. Они прогнозируют её по итогам 2026 года на уровне 6,7-6,9%. Аналитики ждут повышения прогноза по средней ключевой ставке на 2027 год до 11-13%. \"Мы ожидаем, что до конца 2026 года ставка останется на уровне 14%. Поэтому среднегодовая ставка окажется на уровне 14,6%, что соответствует верхней части диапазона, который ЦБ закладывал в июльском прогнозе. К концу 2027 года снижение, по нашим оценкам, ограничится уровнем 12%, в связи с чем среднегодовая ставка может составить 13%, что несколько выше июльского прогноза ЦБ (10,5-12,5%)\", - пишут они в обзоре.\n\nРешение о сохранении ставки на ближайшем заседании Банк России сопроводит жестким сигналом, считают экономисты Альфа-банка. Они отмечают складывающуюся выше ожиданий динамику инфляции, ускоренное повышение тарифов в 2027 году, признаки оживления спроса, снижение нормы сбережений и сохраняющиеся повышенные темпы роста кредитования.\n\n\"Мы ждем паузу на 14% по итогам заседания; кроме того, мы полагаем, что ЦБ РФ даст жесткий сигнал как через решение не рассматривать вопрос о снижении ставки, так и через повышение прогнозного диапазона процентной ставки на 2027 год - мы ожидаем, что новый диапазон будет 11,5-13,5%, т.е. на 100 б.п. выше предыдущего. С учетом складывающегося контекста в экономике мы ожидаем сохранения ставки на 14% до апреля 2027 года и ожидаем среднюю ставку на уровне 13,3% на 2027 год. Динамика инфляции подтверждает наш прогноз 7,5% по итогам 2026 года\", - подчеркивают эксперты. Инфляцию в 2027 году они прогнозируют на уровне 5,8%. Пауза в цикле снижения ставки, по мнению аналитиков Альфа-банка, продлится до апреля 2027 года.\n\n\"ЦБ перестал снижать ставку на фоне ускорения потребления и сохранения давления на цены на топливном рынке. Осенью к набору разовых факторов добавилась повышенная индексация тарифов, рост которых оказался выше заложенного в прогнозы\", - подчеркивают аналитики \"БКС Мир инвестиций\". Они обращают внимание на следующие факторы: повышенные инфляционные ожидания (на уровне 13-15%), инфляция около 7% год к году и 6-6,5% с сезонной корректировкой в годовом выражении, разворот в потребительском кредитовании, рост денежной массы на 1,0-1,5 п.п. выше верхней границы прогноза ЦБ, все еще перегретый рынок труда. В рамках ожиданий остается только прогноз структурного дефицита бюджета, указывают эксперты.\n\n\"Полагаем, что инфляционные ожидания начнут снижаться только в I квартале 2027 года. Этому будет способствовать несколько факторов: прохождение периода после получения платежек по ЖКХ, крепкий рубль и стабильные цены на топливо. Последнее - результат сезонного снижения спроса при отсутствии наращивания предложения. Весной и летом сезонно растущий спрос на топливо может вновь обострить проблему цен\", - пишут аналитики в обзоре.\n\nОни ждут сохранения ставки ЦБ на уровне 14% до конца 2026 года, ставку в 12,25% на конец 2027 года и 13,25% в среднем по следующему году.\n\nНаряду с сохранением ставки и нейтрального сигнала в ближайшую пятницу, ЦБ ужесточит риторику, повысит прогнозы по инфляции и ключевой ставке, считают эксперты УК \"Первая\". Прогноз по инфляции, по их мнению, может быть повышен на 2026 год до 7-8%, на 2027 год - до 4-4,5% (также из-за более существенного роста тарифов в следующем году). Прогноз по ключевой ставке на 2026 год может быть обновлен с учетом уже принятых решений, а на 2027 год - повышен на 0,5-1 п.п. или больше (с июльских 10,5-12,5%), отмечают аналитики.\n\n\"С тактической точки зрения интерес представляет сигнал, который Банк России даст участникам рынка, а в более широком плане - изменение прогноза. Мы полагаем, что сигнал не будет мягким: как минимум нейтральный, но тон всей пресс-конференции, скорее всего, будет достаточно жёстким. Одной из форм сигнала уже стал перечень вариантов, лежащих на столе у Банка России, и вполне возможно, что варианта со снижением ставки в нём, как и в прошлый раз, не будет\", - отмечают аналитики УК \"Ингосстрах инвестиции\". В \"инерционном\" сценарии они ждут инфляцию в 2027 году на уровне 6-7%, ключевую ставку - 13-14%.\n\nЭксперты ИК \"Велес Капитал\" указывают на повышенное устойчивое инфляционное давление и ограничение пространства для смягчения ДКП из-за проинфляционных рисков. \"Мы полагаем, что пауза в октябре продолжится, однако при дальнейшем замедлении инфляции регулятор может вернуться к снижению ставки минимальным шагом в декабре - до 13,75%\", - отмечают аналитики. Существенного пересмотра базового макросценария ЦБ они не ждут (допускают небольшое повышение траектории ключевой ставки на 2027 год).\n\nБанк России может повысить прогноз по инфляции на 2026 год до 6,5-7,5%, средней ставке на 2027 год - до 11-13% (или даже до 11,5-13,5%), считают аналитики Совкомбанка . Они ждут сохранения ставки ЦБ в ближайшую пятницу, сопровождающееся нейтральным сигналом. \"В базовом сценарии мы ожидаем снижения ключевой ставки в следующем году на 100 б.п., до 13% к концу 2027 года. Среднюю ставку в 2027 году мы прогнозируем на уровне 13,5%. В рисковом сценарии - в случае закреплении устойчивой инфляции на повышенных уровнях, роста инфляционных ожиданий, негативных сюрпризов со стороны геополитики, сохранения проблем на топливном рынке - Банк России может начать готовиться к повышению ключевой ставки в следующем году\", - считают эксперты.\n\nАналитики Россельхозбанка, банка \"Русский стандарт\" и \"Цифра брокера\" тоже ждут сохранения ставки в ближайшую пятницу на уровне 14%.\n\n\"Экономическая активность остается умеренной, бизнес-настроения улучшились, а бюджетные проектировки в целом совпали с ожиданиями ЦБ. Однако инфляционные данные за последние недели ухудшились, а внешние риски сохраняются. Поэтому ожидаем, что в эту пятницу Банк России сохранит ключевую ставку на уровне 14% и даст умеренно жесткий сигнал\", - пишут экономисты \"Т-Инвестиций\" в обзоре.\n\nОни ждут сохранения ставки на уровне 14% до конца 2026 года и ее снижения до 13% в среднем в 2027 году. Инфляция, по их прогнозам, в 2026 году составит 7%, в 2027 году - 4,8%, ВВП в этом и следующем годах вырастет на 0,7-0,8%.", "title": "Аналитики ожидают, что ЦБ РФ в пятницу сохранит ключевую ставку на уровне 14%", "topics": [], "regions": [], "countries": [], "published_at": "2026-10-21T16:34:00+00:00"}, "trace": [{"tool": "get_company_metrics", "cached": false, "status": "found", "arguments": {}, "source_ids": ["metric:U_128194:top_okved", "metric:U_128194:counterparties", "metric:U_128194:totals"]}, {"tool": "search_bank_analytics", "cached": false, "status": "unavailable", "arguments": {"query": "ключевая ставка влияние автокредитование"}, "source_ids": []}, {"tool": "search_news", "cached": false, "status": "found", "arguments": {"query": "оптовые автозапчасти спрос кредит"}, "source_ids": ["news:7a502e035b8c88e039bec680010c5929b53f84e4718dac376abe42602a1a502e", "news:6fd817b6b18a3c411d8fd211415892665b9b818b72cc3d64c13f61fe937b10b7", "news:742c81563bbb9a4a170062f93af9d1a556e159e070b75f6400e7620ede26ca10"]}, {"tool": "search_news", "cached": false, "status": "found", "arguments": {"query": "ключевая ставка бизнес кредит оборотный капитал"}, "source_ids": ["news:266d96677a4999c468e5642e31cd0a9909608a4c44310d47c5f2ad2e7bfe3910", "news:7a502e035b8c88e039bec680010c5929b53f84e4718dac376abe42602a1a502e", "news:4e5bb628c20cf849c758d1103a8145bd95a3c597d90bd02f483b75838eb9ac77"]}], "result": {"claims": [{"kind": "fact", "text": "Аналитики единогласно прогнозируют сохранение ключевой ставки ЦБ РФ в ближайшую пятницу на уровне 14%.", "evidence": [{"quote": "Аналитики единогласно прогнозируют сохранение ключевой ставки ЦБ РФ в ближайшую пятницу на уровне 14%", "source_id": "news:9bfb602e317f62a40ab4bd588e14178869a9ee317e02572c6083315e6f4fd66c"}]}, {"kind": "fact", "text": "Эксперты расходятся только в оценке тона сигнала: останется он нейтральным или будет ужесточен.", "evidence": [{"quote": "Эксперты расходятся только в оценке тона сигнала: останется он нейтральным или будет ужесточен.", "source_id": "news:9bfb602e317f62a40ab4bd588e14178869a9ee317e02572c6083315e6f4fd66c"}]}, {"kind": "fact", "text": "Хотя бы часть аналитиков ожидает ужесточение сигнала ЦБ при сохранении ставки.", "evidence": [{"quote": "Решение о сохранении ставки на ближайшем заседании Банк России сопроводит жестким сигналом, считают экономисты Альфа-банка.", "source_id": "news:9bfb602e317f62a40ab4bd588e14178869a9ee317e02572c6083315e6f4fd66c"}]}, {"kind": "fact", "text": "Прогнозы аналитиков допускают возобновление цикла снижения ключевой ставки в будущем, что является прогнозом, а не свершившимся событием.", "evidence": [{"quote": "Возможность для возобновления цикла снижения ключевой ставки может представиться уже на рубеже нового года, если ситуация на топливном рынке продолжит нормализовываться", "source_id": "news:9bfb602e317f62a40ab4bd588e14178869a9ee317e02572c6083315e6f4fd66c"}]}, {"kind": "fact", "text": "Профиль компании указывает на оптовую торговлю автомобильными деталями и узлами (ОКВЭД 45.31.1).", "evidence": [{"quote": "Торговля оптовая автомобильными деталями, узлами и принадлежностями, кроме деятельности агентов", "source_id": "company:U_128194:okved_names"}]}, {"kind": "fact", "text": "Среди банковских сервисов компании указаны кредиты.", "evidence": [{"quote": "Кредиты", "source_id": "company:U_128194:banking_services"}]}, {"kind": "hypothesis", "text": "Сохранение ключевой ставки на уровне 14% при жёстком сигнале может означать, что стоимость заёмного финансирования для компании не снизится в ближайшее время; это гипотеза, поскольку конкретные ставки и объём долга компании неизвестны.", "evidence": [{"quote": "Экономисты Газпромбанка также ждут сохранения ставки на уровне 14% в октябре и декабре из-за того, что инфляция складывается заметно выше ориентиров регулятора.", "source_id": "news:9bfb602e317f62a40ab4bd588e14178869a9ee317e02572c6083315e6f4fd66c"}, {"quote": "Кредиты", "source_id": "company:U_128194:banking_services"}]}], "status": "insufficient_data", "news_id": "9bfb602e317f62a40ab4bd588e14178869a9ee317e02572c6083315e6f4fd66c", "summary": "Данных для оценки влияния на компанию недостаточно. Аналитики единогласно прогнозируют сохранение ключевой ставки ЦБ РФ в ближайшую пятницу на уровне 14%. Сохранение ключевой ставки на уровне 14% при жёстком сигнале может означать, что стоимость заёмного финансирования для компании не снизится в ближайшее время; это гипотеза, поскольку конкретные ставки и объём долга компании неизвестны.", "company_id": "U_128194", "missing_data": ["Условия и ставки по действующим кредитам компании", "Объём и структура долговой нагрузки компании", "Доля заёмных средств в финансировании оборотного капитала", "Показатели рентабельности и прибыли компании", "Ограничение получения контекста: search_bank_analytics (unavailable)"], "follow_up_answer": null}, "company": {"id": "U_128194", "provenance": "dataset", "source_ref": "docs/companies/companies_analytics.json#U_128194", "okved_codes": ["45.31.1"], "okved_names": ["Торговля оптовая автомобильными деталями, узлами и принадлежностями, кроме деятельности агентов"], "ownership_form": "ЧАСТНАЯ СОБСТВЕННОСТЬ", "trade_countries": null, "banking_services": ["РКО", "Кредиты", "Зарплатный проект"], "development_stage": "Оптимизация", "annual_revenue_rub": 7282655891.0, "registration_region": "Воронежская область"}, "history": [], "news_id": "9bfb602e317f62a40ab4bd588e14178869a9ee317e02572c6083315e6f4fd66c", "ranking": {"score": 0, "news_id": "9bfb602e317f62a40ab4bd588e14178869a9ee317e02572c6083315e6f4fd66c", "reasons": [], "eligible": true, "company_id": "U_128194", "missing_data": ["trade_countries", "confirmed_business_exposure"]}, "company_id": "U_128194", "preparation": {"extraction": {"facts": [{"kind": "fact", "text": "Аналитики единогласно прогнозируют сохранение ключевой ставки ЦБ РФ в ближайшую пятницу на уровне 14%.", "evidence": [{"quote": "INTERFAX.RU - Аналитики единогласно прогнозируют сохранение ключевой ставки ЦБ РФ в ближайшую пятницу на уровне 14%.", "source_id": "news:9bfb602e317f62a40ab4bd588e14178869a9ee317e02572c6083315e6f4fd66c"}]}, {"kind": "fact", "text": "Эксперты расходятся только в оценке тона сигнала: останется он нейтральным или будет ужесточен.", "evidence": [{"quote": "Эксперты расходятся только в оценке тона сигнала: останется он нейтральным или будет ужесточен.", "source_id": "news:9bfb602e317f62a40ab4bd588e14178869a9ee317e02572c6083315e6f4fd66c"}]}, {"kind": "fact", "text": "Экономисты также прогнозируют повышение прогноза по инфляции на 2026 год до 6,5-7,5%, на 2027 год - до 4,5-5%.", "evidence": [{"quote": "Экономисты также прогнозируют повышение прогноза по инфляции на 2026 год до 6,5-7,5%, на 2027 год - до 4,5-5%.", "source_id": "news:9bfb602e317f62a40ab4bd588e14178869a9ee317e02572c6083315e6f4fd66c"}]}], "news_id": "9bfb602e317f62a40ab4bd588e14178869a9ee317e02572c6083315e6f4fd66c", "missing_data": []}, "classification": {"topics": ["financial_markets", "regulation"], "news_id": "9bfb602e317f62a40ab4bd588e14178869a9ee317e02572c6083315e6f4fd66c", "evidence": [{"quote": "INTERFAX.RU - Аналитики единогласно прогнозируют сохранение ключевой ставки ЦБ РФ в ближайшую пятницу на уровне 14%.", "source_id": "news:9bfb602e317f62a40ab4bd588e14178869a9ee317e02572c6083315e6f4fd66c"}, {"quote": "Экономисты Газпромбанка также ждут сохранения ставки на уровне 14% в октябре и декабре из-за того, что инфляция складывается заметно выше ориентиров регулятора.", "source_id": "news:9bfb602e317f62a40ab4bd588e14178869a9ee317e02572c6083315e6f4fd66c"}, {"quote": "Решение о сохранении ставки на ближайшем заседании Банк России сопроводит жестким сигналом, считают экономисты Альфа-банка.", "source_id": "news:9bfb602e317f62a40ab4bd588e14178869a9ee317e02572c6083315e6f4fd66c"}], "business_relevant": true}}, "news_metadata": {"publisher": "Интерфакс", "source_id": "interfax", "limitations": ["Extracted public body; completeness and source claims are not independently verified."], "collected_at": "2026-10-21T19:59:48.609774Z", "date_provenance": "html:article:published_time", "extraction_method": "css:[itemprop=\"articleBody\"]"}, "research_stop": "model_finished", "retrieved_sources": [{"url": null, "kind": "metric", "text": "Агрегат