e_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}, {"quote": "В совокупности со снижением спроса со стороны азиатских НПЗ это приводит к расширению дисконтов на российскую нефть.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}], "business_relevant": true}}, "bank_metadata": {"bank:alfa-macro-1h26#5be166b212bfe1aa": {"pages": [4], "document_id": "alfa-macro-1h26", "source_name": "ALFA-macro_stat1H26.pdf", "published_at": "2026-07-31T00:00:00+00:00", "section_path": ["Приложение"], "document_title": "Макростатистика 1П26"}, "bank:alfa-consumption#f2759ca34798df58": {"pages": [1], "document_id": "alfa-consumption", "source_name": "ALFA-consumption.pdf", "published_at": "2026-08-05T00:00:00+00:00", "section_path": [], "document_title": "Потребление на пике"}, "bank:alfa-fi-strategy-3q26#574bb0d69ea9a5f9": {"pages": [10], "document_id": "alfa-fi-strategy-3q26", "source_name": "FI_Strategy_3Q26_22072026.pdf", "published_at": "2026-07-22T00:00:00+00:00", "section_path": ["Кредит Рынок НЕфиксированного дохода"], "document_title": "Долговой рынок"}, "bank:alfa-fi-strategy-3q26#62f0ad597286116f": {"pages": [10], "document_id": "alfa-fi-strategy-3q26", "source_name": "FI_Strategy_3Q26_22072026.pdf", "published_at": "2026-07-22T00:00:00+00:00", "section_path": ["Кредит Рынок НЕфиксированного дохода"], "document_title": "Долговой рынок"}, "bank:alfa-bond-brief-2026-09-14#7512d2f7d36f2840": {"pages": [3, 4], "document_id": "alfa-bond-brief-2026-09-14", "source_name": "Бонд_Бриф_14092026.pdf", "published_at": "2026-09-14T00:00:00+00:00", "section_path": ["Финансовые результаты Компании на основе МСФО-отчетности:"], "document_title": "Бонд Бриф: Итоги недели"}, "bank:alfa-policy-rate-2026-09-11#debf21113eb96a49": {"pages": [1], "document_id": "alfa-policy-rate-2026-09-11", "source_name": "ALFA-Macro_Insights-Policy_Rate_11Sep.pdf", "published_at": "2026-09-11T00:00:00+00:00", "section_path": ["Ставка без изменени