l, "published_at": "2026-10-22T09:22:47+00:00"}, {"url": null, "kind": "metric", "text": "Агрегаты платежей за неизвестный период. Дат платежей нет; динамика и сезонность неизвестны. География отражает регистрацию контрагентов, а не место операций; оборот не равен выручке. Роли покупателя/поставщика и причинная связь с новостью не установлены.\n{\"totals\": {\"incoming_amount_rub\": 2628761000, \"outgoing_amount_rub\": 426520000, \"turnover_rub\": 3055281000, \"incoming_payments_count\": 9905, \"outgoing_payments_count\": 1014, \"edges_count\": 365, \"unique_counterparties_count\": 328, \"external_counterparties_count\": 326, \"intragroup_counterparties_count\": 2, \"intragroup_amount_rub\": 172841000, \"intragroup_share_pct\": 5.66, \"average_edge_amount_rub\": 8370633}}", "title": "Агрегаты платежей: totals", "is_demo": false, "locator": "docs/companies/companies_analytics.json#U_46911/payments/totals", "publisher": null, "source_id": "metric:U_46911:totals", "company_id": "U_46911", "collected_at": null, "published_at": "2026-10-22T09:22:47+00:00"}, {"url": "https://www.interfax.ru/business/1124059", "kind": "news", "text": "Инфляция в РФ с 13 по 19 октября составила 0,05%, годовая замедлилась до 7,15%\nМосква. 21 октября. INTERFAX.RU - Инфляция в РФ с 13 по 19 октября составила 0,05% после 0,11% с 6 по 12 октября, 0,96% с 29 сентября по 5 октября (\"тарифная неделя\" после индексации с 1 октября стоимости услуг ЖКХ), 0,12% с 22 по 28 сентября, 0,06% с 15 по 21 сентября, 0,02% с 8 по", "title": "Инфляция в РФ с 13 по 19 октября составила 0,05%, годовая замедлилась до 7,15%", "is_demo": false, "locator": "https://www.interfax.ru/business/1124059", "publisher": "Интерфакс", "source_id": "news:266d96677a4999c468e5642e31cd0a9909608a4c44310d47c5f2ad2e7bfe3910", "company_id": null, "collected_at": "2026-10-21T19:59:57.683146+00:00", "published_at": "2026-10-21T16:03:00+00:00"}, {"url": "https://www.interfax.ru/business/1124072", "kind": "news", "text": "Рубль укрепляется к мировым валютам четвертый день подряд\nМосква. 21 октября. INTERFAX.RU - Китайский юань умеренно снизился на Московской бирже по итогам торгов в среду. Курс рубля укрепился к основным мировым валютам четвертый торговый день подряд на фоне высоких мировых цен на нефть и приближающегося налогового периода октября.\n\nСтоимость юаня по данным на 19:00 составила 12,2255 рубля, что на 11,95 копейки (на 0,97%) ниже уровня", "title": "Рубль укрепляется к мировым валютам четвертый день подряд", "is_demo": false, "locator": "https://www.interfax.ru/business/1124072", "publisher": "Интерфакс", "source_id": "news:742c81563bbb9a4a170062f93af9d1a556e159e070b75f6400e7620ede26ca10", "company_id": null, "collected_at": "2026-10-21T19:59:43.597087+00:00", "published_at": "2026-10-21T16:54:00+00:00"}, {"url": "https://www.kommersant.ru/doc/9044169", "kind": "news", "text": "Ставки на перевозку российской нефти выросли до рекордного уровня\nРост мировых ставок фрахта и сохраняющиеся риски для судоходства разогнали стоимость транспортировки российской нефти. По данным Argus, аренда судов для перевозки сырья из Новороссийска и Приморска подорожала до максимума за историю наблюдений — $27–48 за баррель. В совокупности со снижением спроса со стороны азиатских НПЗ это приводит к расширению дисконтов на российскую нефть. Однако, при этом мировые цены на нефтепродукты", "title": "Ставки на перевозку российской нефти выросли до рекордного уровня", "is_demo": false, "locator": "https://www.kommersant.ru/doc/9044169", "publisher": "Коммерсантъ", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e", "company_id": null, "collected_at": "2026-10-21T19:59:58.568791+00:00", "published_at": "2026-10-21T16:14:44+00:00"}]}', '2026-10-22 13:45:06.870942+00', NULL, '2026-10-23 17:26:13.378314+00', '2026-10-23 18:06:40.280148+00') ON CONFLICT DO NOTHING;
INSERT INTO public.news_company_links (news_id, company_id, news_hash, company_hash, active, match_method, match_score, match_reasons, topics, importance, importance_status, importance_reason, importance_evidence, importance_method, importance_attempts, analysis_status, analysis_run_id, analysis_result, analysis_as_of, error_code, matched_at, updated_at) VALUES ('9dbc2e8918c86a6fc71dae06e658cb04092d7ab0878e214f4f47aa153952ef5c', 'U_46827', '09169b72ee191aee3bb3edce4dde76fa6f9ef88ad92330ba5c3e8609c8b0980f', '4566cd9e6185ca26a7c9951bef9937c3ef8d4124997006a39c2270f778793396', true, 'hybrid', 0.07233704, '[{"kind": "industry", "okved": "52.29", "query": "Транспортная логистика, порты, грузоперевозки и ставки фрахта", "lexical_query": "\"перевозки\" OR \"грузоперевозки\" OR \"пароходства\" OR \"порты\" OR \"фрахт\""}]', '["logistics", "other_business", "construction"]', 'medium', 'ready', 'Развитие нового транспортного коридора («Маршрут Трампа») потенциально создает новые возможности для логистической деятельности, к которой относится компания (ОКВЭД 52.29). Однако прямая связь ограничена, так как проект находится на стадии планирования (начало работ в 2027 году) и регулируется международными соглашениями.', '[{"quote": "«Маршрут Трампа» должен соединить западные районы Азербайджана с его эксклавом — Нахичеванской Автономной Республикой через Сюникскую область Армении.", "source_id": "news:9dbc2e8918c86a6fc71dae06e658cb04092d7ab0878e214f4f47aa153952ef5c"}, {"quote": "[\"52.29\"]", "source_id": "company:U_46827:okved_codes"}]', 'triage', 0, 'pending', NULL, NULL, NULL, NULL, '2026-10-23 17:26:13.397853+00', '2026-10-23 18:06:39.717348+00') ON CONFLICT DO NOTHING;
INSERT INTO public.news_company_links (news_id, company_id, news_hash, company_hash, active, match_method, match_score, match_reasons, topics, importance, importance_status, importance_reason, importance_evidence, importance_method, importance_attempts, analysis_status, analysis_run_id, analysis_result, analysis_as_of, error_code, matched_at, updated_at) VALUES ('9bfb602e317f62a40ab4bd588e14178869a9ee317e02572c6083315e6f4fd66c', 'U_99802', 'a15e983f3a179662b0693c06561d9a81741499b3d42707108226083a234d93e1', '9211a0383bfb614f85fc8d7994a03cc507d7bafbd112b0f64c0f6db0dbb37b7f', true, 'hybrid', 0.09677419, '[{"kind": "financing", "query": "Решения и прогнозы ЦБ по ключевой ставке, стоимость кредитования", "lexical_query": "\"ключевая ставка\" OR \"ставка ЦБ\""}]', '["financial_markets", "regulation"]', 'low', 'ready', 'Новость касается макроэкономических прогнозов ЦБ РФ по ключевой ставке и инфляции. Хотя это влияет на общую экономическую среду, в тексте нет прямой связи с деятельностью компании, занимающейся арендой недвижимости.', '[{"quote": "INTERFAX.RU - Аналитики единогласно прогнозируют сохранение ключевой ставки ЦБ РФ в ближайшую пятницу на уровне 14%.", "source_id": "news:9bfb602e317f62a40ab4bd588e14178869a9ee317e02572c6083315e6f4fd66c"}, {"quote": "[\"68.20.2\"]", "source_id": "company:U_99802:okved_codes"}]', 'triage', 0, 'pending', NULL, NULL, NULL, NULL, '2026-10-23 17:26:13.413467+00', '2026-10-23 18:06:41.050958+00') ON CONFLICT DO NOTHING;
INSERT INTO public.news_company_links (news_id, company_id, news_hash, company_hash, active, match_method, match_score, match_reasons, topics, importance, importance_status, importance_reason, importance_evidence, importance_method, importance_attempts, analysis_status, analysis_run_id, analysis_result, analysis_as_of, error_code, matched_at, updated_at) VALUES ('8a074a8f338d8abb583c6316e309f6a4408c6483796105bbc0cea0c370367cb8', 'U_99802', '3ec3f96c9e30f48e730e22686459e2c2e8ae7dc01cae695acec99e2d04c8dfac', '9211a0383bfb614f85fc8d7994a03cc507d7bafbd112b0f64c0f6db0dbb37b7f', true, 'hybrid', 0.07562724, '[{"kind": "counterparty", "okved": "41", "query": "Строительство зданий, спрос и стоимость строительных материалов", "source_id": "metric:U_99802:top_okved", "limitation": "Известна только отрасль контрагента и доля в обороте; роль и текущая экспозиция не установлены.", "lexical_query": "\"строительство\" OR \"стройматериалы\"", "turnover_share_pct": 28.14}]', '["energy", "construction"]', 'high', 'ready', 'Строительство АЭС «Пакш-2» в Венгрии является ключевым проектом, напрямую связанным с деятельностью Госкорпорации «Росатом», включая изготовление оборудования и соблюдение графиков работ.', '[{"quote": "Госкорпорация « Росатом » продолжает строительство атомной электростанции «Пакш-2» в Венгрии в соответствии с графиком, согласованным с заказчиком.", "source_id": "news:8a074a8f338d8abb583c6316e309f6a4408c6483796105bbc0cea0c370367cb8"}, {"quote": "[\"Аренда и управление собственным или арендованным нежилым недвижимым имуществом\"]", "source_id": "company:U_99802:okved_names"}]', 'triage', 0, 'pending', NULL, NULL, NULL, NULL, '2026-10-23 17:26:13.427499+00', '2026-10-23 18:06:41.073783+00') ON CONFLICT DO NOTHING;
INSERT INTO public.news_company_links (news_id, company_id, news_hash, company_hash, active, match_method, match_score, match_reasons, topics, importance, importance_status, importance_reason, importance_evidence, importance_method, importance_attempts, analysis_status, analysis_run_id, analysis_result, analysis_as_of, error_code, matched_at, updated_at) VALUES ('1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e', 'U_128194', '792ad3361e59e53c8f9429ade9bda9c91daef1938a04d82a9594cc614c153008', '8acd4495d1663cd05112f99ff359a881362f97810afaa5656c6f6b87820cb752', true, 'saved_analysis', NULL, '[{"kind": "saved_analysis"}]', '["energy", "logistics"]', 'low', 'ready', 'Компания занимается оптовой торговлей автомобильными деталями, в то время как новость касается изменения ставок на фрахт и транспортировку российской нефти. Прямая связь между деятельностью компании и рынком морских перевозок нефти отсутствует.', '[{"quote": "Рост мировых ставок фрахта и сохраняющиеся риски для судоходства разогнали стоимость транспортировки российской нефти.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}, {"quote": "[\"45.31.1\"]", "source_id": "company:U_128194:okved_codes"}]', 'triage', 0, 'ready', NULL, '{"mode": "live", "as_of": "2026-10-22T13:45:06.870942+00:00", "event": {"id": "1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e", "url": "https://www.kommersant.ru/doc/9044169", "text": "Рост мировых ставок фрахта и сохраняющиеся риски для судоходства разогнали стоимость транспортировки российской нефти. По данным Argus, аренда судов для перевозки сырья из Новороссийска и Приморска подорожала до максимума за историю наблюдений — $27–48 за баррель. В совокупности со снижением спроса со стороны азиатских НПЗ это приводит к расширению дисконтов на российскую нефть. Однако, при этом мировые цены на нефтепродукты сохраняются на высоком уровне. В условиях низких запасов из-за Ормузского кризиса это формирует повышенный спрос на нефть и создает благоприятные условия для российского экспорта, считают эксперты. Подробности — в материале «У фрахта глаза велики» .", "title": "Ставки на перевозку российской нефти выросли до рекордного уровня", "topics": [], "regions": [], "countries": [], "published_at": "2026-10-21T16:14:44+00:00"}, "trace": [{"tool": "get_company_metrics", "cached": false, "status": "found", "arguments": {}, "source_ids": ["metric:U_128194:top_okved", "metric:U_128194:counterparties", "metric:U_128194:totals"]}, {"tool": "search_news", "cached": false, "status": "found", "arguments": {"query": "автозапчасти оптовые продажи"}, "source_ids": ["news:979c31165ea59654907f85e01f2977b9b466dd2589ba8a9b4ff87f9feb4d2d25", "news:ca9b8b908ca919199a8c6c3d95d1bee5b77dcaa38b6be2d38f782abafd2a7ca5", "news:8e51d67342b0e801ee2add6a2a595aa239cbd27a4a413c350c6e3da4839a79ae"]}, {"tool": "search_news", "cached": false, "status": "found", "arguments": {"query": "ставки фрахт перевозки нефти"}, "source_ids": ["news:742c81563bbb9a4a170062f93af9d1a556e159e070b75f6400e7620ede26ca10", "news:979c31165ea59654907f85e01f2977b9b466dd2589ba8a9b4ff87f9feb4d2d25", "news:35b96e76fbd32900239619f2a3c327e718ad47c05aca6cfc7a0f0cc78c3f01b6"]}, {"tool": "search_bank_analytics", "cached": false, "status": "unavailable", "arguments": {"query": "автомобильные запчасти авторынок отрасль"}, "source_ids": []}, {"tool": "search_bank_analytics", "cached": true, "status": "unavailable", "arguments": {"query": "логистика фрахт нефть ставки"}, "source_ids": []}], "result": {"claims": [{"kind": "fact", "text": "По данным Argus, аренда судов для перевозки сырья из Новороссийска и Приморска подорожала до максимума за историю наблюдений — $27–48 за баррель.", "evidence": [{"quote": "По данным Argus, аренда судов для перевозки сырья из Новороссийска и Приморска подорожала до максимума за историю наблюдений — $27–48 за баррель.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}]}, {"kind": "fact", "text": "В совокупности со снижением спроса со стороны азиатских НПЗ это приводит к расширению дисконтов на российскую нефть.", "evidence": [{"quote": "В совокупности со снижением спроса со стороны азиатских НПЗ это приводит к расширению дисконтов на российскую нефть.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}]}, {"kind": "fact", "text": "В условиях низких запасов из-за Ормузского кризиса это формирует повышенный спрос на нефть и создает благоприятные условия для российского экспорта, считают эксперты.", "evidence": [{"quote": "В условиях низких запасов из-за Ормузского кризиса это формирует повышенный спрос на нефть и создает благоприятные условия для российского экспорта, считают эксперты.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}]}, {"kind": "fact", "text": "Основной ОКВЭД компании — 45.31.1 «Торговля оптовая автомобильными деталями, узлами и принадлежностями, кроме деятельности агентов».", "evidence": [{"quote": "Торговля оптовая автомобильными деталями, узлами и принадлежностями, кроме деятельности агентов", "source_id": "company:U_128194:okved_names"}]}, {"kind": "fact", "text": "Среди контрагентов компании по агрегатам платежей присутствует ОКВЭД 46.71 «Торговля оптовая твердым, жидким и газообразным топливом и подобными продуктами» с долей 1.14%.", "evidence": [{"quote": "\"okved_code\": \"46.71\", \"okved_name\": \"Торговля оптовая твердым, жидким и газообразным топливом и подобными продуктами\", \"counterparties_count\": 6, \"amount_rub\": 62493000, \"share_pct\": 1.14", "source_id": "metric:U_128194:top_okved"}]}, {"kind": "hypothesis", "text": "Прямая применимость новости к компании не подтверждается: новость касается перевозки нефти, тогда как основной вид деятельности компании — оптовая торговля автозапчастями.", "evidence": [{"quote": "По данным Argus, аренда судов для перевозки сырья из Новороссийска и Приморска подорожала до максимума за историю наблюдений — $27–48 за баррель.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}, {"quote": "Торговля оптовая автомобильными деталями, узлами и принадлежностями, кроме деятельности агентов", "source_id": "company:U_128194:okved_names"}]}, {"kind": "hypothesis", "text": "Возможна косвенная экспозиция через контрагентов в оптовой торговле топливом, однако роли и причинная связь с новостью не установлены.", "evidence": [{"quote": "\"okved_code\": \"46.71\", \"okved_name\": \"Торговля оптовая твердым, жидким и газообразным топливом и подобными продуктами\", \"counterparties_count\": 6, \"amount_rub\": 62493000, \"share_pct\": 1.14", "source_id": "metric:U_128194:top_okved"}, {"quote": "Роли покупателя/поставщика и причинная связь с новостью не установлены.", "source_id": "metric:U_128194:top_okved"}]}], "status": "supported", "news_id": "1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e", "summary": "По данным Argus, аренда судов для перевозки сырья из Новороссийска и Приморска подорожала до максимума за историю наблюдений — $27–48 за баррель. Прямая применимость новости к компании не подтверждается: новость касается перевозки нефти, тогда как основной вид деятельности компании — оптовая торговля автозапчастями.", "company_id": "U_128194", "missing_data": ["Нет данных о наличии у компании деятельности, связанной с перевозкой или торговлей нефтью.", "Нет данных о доле выручки или платежей, приходящейся на контрагентов топливного сектора.", "Нет сведений о влиянии ставок фрахта на перевозку нефти на финансовые или операционные показатели компании.", "Ограничение получения контекста: search_bank_analytics (unavailable)"], "follow_up_answer": null}, "company": {"id": "U_128194", "provenance": "dataset", "source_ref": "docs/companies/companies_analytics.json#U_128194", "okved_codes": ["45.31.1"], "okved_names": ["Торговля оптовая автомобильными деталями, узлами и принадлежностями, кроме деятельности агентов"], "ownership_form": "