INSERT INTO public.news_company_links (news_id, company_id, news_hash, company_hash, active, match_method, match_score, match_reasons, topics, importance, importance_status, importance_reason, importance_evidence, importance_method, importance_attempts, analysis_status, analysis_run_id, analysis_result, analysis_as_of, error_code, matched_at, updated_at) VALUES ('9dbc2e8918c86a6fc71dae06e658cb04092d7ab0878e214f4f47aa153952ef5c', 'U_46911', '09169b72ee191aee3bb3edce4dde76fa6f9ef88ad92330ba5c3e8609c8b0980f', '049ef2d8eac191696be054dfbff8438fdf2aa849be8b13ffe25f101388468795', true, 'hybrid', 0.07233704, '[{"kind": "industry", "okved": "52.29", "query": "Транспортная логистика, порты, грузоперевозки и ставки фрахта", "lexical_query": "\"перевозки\" OR \"грузоперевозки\" OR \"пароходства\" OR \"порты\" OR \"фрахт\""}]', '["logistics", "other_business", "construction"]', 'medium', 'ready', 'Проект «Маршрут Трампа» предполагает создание новой транспортной инфраструктуры через Армению. Поскольку компания занимается вспомогательной деятельностью, связанной с перевозками (ОКВЭД 52.29), развитие новых логистических коридоров может создать косвенные возможности для расширения её деятельности в будущем.', '[{"quote": "«Маршрут Трампа» должен соединить западные районы Азербайджана с его эксклавом — Нахичеванской Автономной Республикой через Сюникскую область Армении.", "source_id": "news:9dbc2e8918c86a6fc71dae06e658cb04092d7ab0878e214f4f47aa153952ef5c"}, {"quote": "[\"52.29\"]", "source_id": "company:U_46911:okved_codes"}]', 'triage', 0, 'pending', NULL, NULL, NULL, NULL, '2026-10-23 17:26:13.371298+00', '2026-10-23 18:06:40.267956+00') ON CONFLICT DO NOTHING;
INSERT INTO public.news_company_links (news_id, company_id, news_hash, company_hash, active, match_method, match_score, match_reasons, topics, importance, importance_status, importance_reason, importance_evidence, importance_method, importance_attempts, analysis_status, analysis_run_id, analysis_result, analysis_as_of, error_code, matched_at, updated_at) VALUES ('6a98927413ff76054f70855c65b333e121bdd956775446e54296929494929ce4', 'U_99802', 'c85b4881d72528908e34bd0edd5ccadac2f67f0916aaf9785d92014c9d40fb11', '9211a0383bfb614f85fc8d7994a03cc507d7bafbd112b0f64c0f6db0dbb37b7f', true, 'hybrid', 0.09576613, '[{"kind": "counterparty", "okved": "56", "query": "Общественное питание, рестораны и цены на продукты", "source_id": "metric:U_99802:top_okved", "limitation": "Известна только отрасль контрагента и доля в обороте; роль и текущая экспозиция не установлены.", "lexical_query": "\"рестораны\" OR \"общественное питание\" OR \"продукты\" OR \"овощи\"", "turnover_share_pct": 49.46}]', '["retail_ecommerce", "other_business"]', 'low', 'ready', 'Компания занимается арендой и управлением нежилой недвижимостью. Изменение цен на овощи и фрукты на рынке не имеет прямой или существенной связи с её основной деятельностью.', '[{"quote": "INTERFAX.RU - Цены на овощи и фрукты в РФ с 13 по 19 октября повысились на 0,7%, сообщил Росстат в среду.", "source_id": "news:6a98927413ff76054f70855c65b333e121bdd956775446e54296929494929ce4"}, {"quote": "[\"68.20.2\"]", "source_id": "company:U_99802:okved_codes"}]', 'triage', 0, 'pending', NULL, NULL, NULL, NULL, '2026-10-23 17:26:13.42047+00', '2026-10-23 18:06:41.062225+00') ON CONFLICT DO NOTHING;
INSERT INTO public.news_company_links (news_id, company_id, news_hash, company_hash, active, match_method, match_score, match_reasons, topics, importance, importance_status, importance_reason, importance_evidence, importance_method, importance_attempts, analysis_status, analysis_run_id, analysis_result, analysis_as_of, error_code, matched_at, updated_at) VALUES ('9bfb602e317f62a40ab4bd588e14178869a9ee317e02572c6083315e6f4fd66c', 'U_46827', 'a15e983f3a179662b0693c06561d9a81741499b3d42707108226083a234d93e1', '4566cd9e6185ca26a7c9951bef9937c3ef8d4124997006a39c2270f778793396', true, 'hybrid', 0.09677419, '[{"kind": "financing", "query": "Решения и прогнозы ЦБ по ключевой ставке, стоимость кредитования", "lexical_query": "\"ключевая ставка\" OR \"ставка ЦБ\""}]', '["financial_markets", "regulation"]', 'medium', 'ready', 'Решение ЦБ РФ по ключевой ставке косвенно влияет на компанию через стоимость обслуживания кредитов, которыми она пользуется (banking_services: credit), и общие условия кредитования в экономике.', '[{"quote": "Аналитики ожидают, что ЦБ РФ в пятницу сохранит ключевую ставку на уровне 14%", "source_id": "news:9bfb602e317f62a40ab4bd588e14178869a9ee317e02572c6083315e6f4fd66c"}, {"quote": "[\"cash_register\", \"credit\", \"payroll\"]", "source_id": "company:U_46827:banking_services"}]', 'triage', 0, 'pending', NULL, NULL, NULL, NULL, '2026-10-23 17:26:13.406602+00', '2026-10-23 18:06:39.729462+00') ON CONFLICT DO NOTHING;
INSERT INTO public.news_company_links (news_id, company_id, news_hash, company_hash, active, match_method, match_score, match_reasons, topics, importance, importance_status, importance_reason, importance_evidence, importance_method, importance_attempts, analysis_status, analysis_run_id, analysis_result, analysis_as_of, error_code, matched_at, updated_at) VALUES ('1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e', 'U_125887', '792ad3361e59e53c8f9429ade9bda9c91daef1938a04d82a9594cc614c153008', '3dffbda6323de71ae64a73cafb595d71b5f6941b16fc9d4edb9e57f00eaa8093', true, 'company_embedding', 0.807990312576294, '[{"kind": "semantic", "limitation": "Сходство определяет кандидатов, а не доказанное влияние.", "matched_topics": []}]', '["energy", "logistics"]', 'low', 'ready', 'Компания занимается оптовой торговлей автомобильными деталями (ОКВЭД 45.31), в то время как новость касается изменения стоимости фрахта и логистики российской нефти. Прямая связь между рынком нефтепродуктов и деятельностью компании отсутствует.', '[{"quote": "Рост мировых ставок фрахта и сохраняющиеся риски для судоходства разогнали стоимость транспортировки российской нефти.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}, {"quote": "[\"45.31\"]", "source_id": "company:U_125887:okved_codes"}]', 'triage', 0, 'pending', NULL, NULL, NULL, NULL, '2026-10-23 17:29:47.235479+00', '2026-10-23 17:29:50.012791+00') ON CONFLICT DO NOTHING;
INSERT INTO public.news_company_links (news_id, company_id, news_hash, company_hash, active, match_method, match_score, match_reasons, topics, importance, importance_status, importance_reason, importance_evidence, importance_method, importance_attempts, analysis_status, analysis_run_id, analysis_result, analysis_as_of, error_code, matched_at, updated_at) VALUES ('1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e', 'U_99802', '792ad3361e59e53c8f9429ade9bda9c91daef1938a04d82a9594cc614c153008', '9211a0383bfb614f85fc8d7994a03cc507d7bafbd112b0f64c0f6db0dbb37b7f', true, 'company_embedding', 0.8339937925338745, '[{"kind": "semantic", "limitation": "Сходство определяет кандидатов, а не доказанное влияние.", "matched_topics": []}]', '["energy", "logistics"]', 'low', 'ready', 'Компания занимается арендой нежилой недвижимости (ОКВЭД 68.20.2). Новости о росте ставок на фрахт и транспортировку нефти напрямую не связаны с её деятельностью, так как она не является логистическим или энергетическим оператором.', '[{"quote": "Рост мировых ставок фрахта и сохраняющиеся риски для судоходства разогнали стоимость транспортировки российской нефти.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}, {"quote": "[\"68.20.2\"]", "source_id": "company:U_99802:okved_codes"}]', 'triage', 0, 'partial', NULL, '{"mode": "live", "as_of": "2026-10-22T13:45:06.870942+00:00", "event": {"id": "1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e", "url": "https://www.kommersant.ru/doc/9044169", "text": "Рост мировых ставок фрахта и сохраняющиеся риски для судоходства разогнали стоимость транспортировки российской нефти. По данным Argus, аренда судов для перевозки сырья из Новороссийска и Приморска подорожала до максимума за историю наблюдений — $27–48 за баррель. В совокупности со снижением спроса со стороны азиатских НПЗ это приводит к расширению дисконтов на российскую нефть. Однако, при этом мировые цены на нефтепродукты сохраняются на высоком уровне. В условиях низких запасов из-за Ормузского кризиса это формирует повышенный спрос на нефть и создает благоприятные условия для российского экспорта, считают эксперты. Подробности — в материале «У фрахта глаза велики» .", "title": "Ставки на перевозку российской нефти выросли до рекордного уровня", "topics": [], "regions": [], "countries": [], "published_at": "2026-10-21T16:14:44+00:00"}, "trace": [{"tool": "get_company_metrics", "cached": false, "status": "found", "arguments": {}, "source_ids": ["metric:U_99802:top_okved", "metric:U_99802:counterparties", "metric:U_99802:totals"]}, {"tool": "search_bank_analytics", "cached": false, "status": "unavailable", "arguments": {"query": "фрахт нефть ставки"}, "source_ids": []}, {"tool": "search_news", "cached": false, "status": "found", "arguments": {"query": "ставки фрахта нефть экспорт"}, "source_ids": ["news:742c81563bbb9a4a170062f93af9d1a556e159e070b75f6400e7620ede26ca10", "news:979c31165ea59654907f85e01f2977b9b466dd2589ba8a9b4ff87f9feb4d2d25", "news:c534459f12447b229f428065b3ca1e82259c2e2ea5708d5967d9d4073cd4c6cd"]}, {"tool": "search_news", "cached": false, "status": "found", "arguments": {"query": "аренда нежилой недвижимости Московская область"}, "source_ids": ["news:bdf5b6841ab2b1d20c6a6590f107f65223470143f0e9270b90656d36ade20fec", "news:742c81563bbb9a4a170062f93af9d1a556e159e070b75f6400e7620ede26ca10", "news:58584fcdfd6d53847a6ac0dab27f4b883e6c65a041c54dbcbc18d67060d28d6b"]}], "result": {"claims": [{"kind": "fact", "text": "По данным Argus, аренда судов для перевозки российской нефти из Новороссийска и Приморска подорожала до исторического максимума — $27–48 за баррель.", "evidence": [{"quote": "По данным Argus, аренда судов для перевозки сырья из Новороссийска и Приморска подорожала до максимума за историю наблюдений — $27–48 за баррель.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}]}, {"kind": "fact", "text": "Снижение спроса со стороны азиатских НПЗ вместе с ростом фрахта приводит к расширению дисконтов на российскую нефть.", "evidence": [{"quote": "В совокупности со снижением спроса со стороны азиатских НПЗ это приводит к расширению дисконтов на российскую нефть.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}]}, {"kind": "fact", "text": "Эксперты считают, что низкие запасы из-за Ормузского кризиса формируют повышенный спрос на нефть и создают благоприятные условия для российского экспорта.", "evidence": [{"quote": "В условиях низких запасов из-за Ормузского кризиса это формирует повышенный спрос на нефть и создает благоприятные условия для российского экспорта, считают эксперты.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}]}, {"kind": "hypothesis", "text": "Новость об экспорте нефти может не относиться к U_99802, поскольку основной ОКВЭД компании — 68.20.2 «Аренда и управление собственным или арендованным нежилым недвижимым имуществом».", "evidence": [{"quote": "[\"68.20.2\"]", "source_id": "company:U_99802:okved_codes"}, {"quote": "\"Аренда и управление собственным или арендованным нежилым недвижимым имуществом\"", "source_id": "company:U_99802:okved_names"}]}, {"kind": "hypothesis", "text": "В агрегатах платежей U_99802 в топ-3 отраслей контрагентов входят общепит, строительство и инженерное проектирование, а не нефтедобыча или морская логистика; однако это не доказывает отсутствие нефтяной экспозиции, так как топ-3 не является полным перечнем.", "evidence": [{"quote": "Деятельность по предоставлению продуктов питания и напитков", "source_id": "metric:U_99802:top_okved"}, {"quote": "Строительство зданий", "source_id": "metric:U_99802:top_okved"}, {"quote": "Деятельность в области архитектуры и инженерно-технического проектирования", "source_id": "metric:U_99802:top_okved"}]}, {"kind": "hypothesis", "text": "Регистрация в Московской области не доказывает место ведения операций; в профиле нет данных об участии в морских перевозках или экспорте нефти.", "evidence": [{"quote": "\"Московская область\"", "source_id": "company:U_99802:registration_region"}]}], "status": "insufficient_data", "news_id": "1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e", "summary": "Данных для оценки влияния на компанию недостаточно. По данным Argus, аренда судов для перевозки российской нефти из Новороссийска и Приморска подорожала до исторического максимума — $27–48 за баррель.", "company_id": "U_99802", "missing_data": ["Сведения об участии компании в перевозках, фрахте или экспорте нефти", "Роли контрагентов и причинная связь с новостью не установлены", "Год выручки не указан, поэтому 16 953 859 423 руб. не является текущей выручкой", "Полный перечень отраслей контрагентов отсутствует", "Ограничение получения контекста: search_bank_analytics (unavailable)"], "follow_up_answer": null}, "company": {"id": "U_99802", "provenance": "dataset", "source_ref": "docs/companies/companies_analytics.json#U_99802", "okved_codes": ["68.20.2"], "okved_names": ["Аренда и управление собственным или арендованным нежилым недвижимым имуществом"], "ownership_form": "ЧАСТНАЯ СОБСТВЕННОСТЬ", "trade_countries": null, "banking_services": ["Депозиты"], "development_stage": "Оптимизация", "annual_revenue_rub": 16953859423.0, "registration_region": "Московская область"}, "history": [], "news_id": "1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e", "ranking": {"score": 0, "news_id": "1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e", "reasons": [], "eligible": true, "company_id": "U_99802", "missing_data": ["trade_countries", "confirmed_business_exposure"]}, "company_id": "U_99802", "preparation": {"extraction": {"facts": [{"kind": "fact", "text": "По данным Argus, аренда судов для перевозки сырья из Новороссийска и Приморска подорожала до максимума за историю наблюдений — $27–48 за баррель.", "evidence": [{"quote": "По данным Argus, аренда судов для перевозки сырья из Новороссийска и Приморска подорожала до максимума за историю наблюдений — $27–48 за баррель.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}]}, {"kind": "fact", "text": "В совокупности со снижением спроса со стороны азиатских НПЗ это приводит к расширению дисконтов на российскую нефть.", "evidence": [{"quote": "В совокупности со снижением спроса со стороны азиатских НПЗ это приводит к расширению дисконтов на российскую нефть.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}]}, {"kind": "fact", "text": "В условиях низких запасов из-за Ормузского кризиса это формирует повышенный спрос на нефть и создает благоприятные условия для российского экспорта, считают эксперты.", "evidence": [{"quote": "В условиях низких запасов из-за Ормузского кризиса это формирует повышенный спрос на нефть и создает благоприятные условия для российского экспорта, считают эксперты.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}]}], "news_id": "1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e", "missing_data": []}, "classification": {"topics": ["energy", "logistics"], "news_id": "1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e", "evidence": [{"quote": "По данным Argus, аренда судов для перевозки сырья из Новороссийска и Приморска подорожала до максимума за историю наблюдений — $27–48 за баррель.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}, {"quote": "Рост мировых ставок фрахта и сохраняющиеся риски для судоходства разогнали стоимость транспортировки российской нефти.", "source_id": "news:1056dce3cfa282c8aee1ecd173c5273091e4715beda0b3930c733a3261c46b2e"}], "business_relevant": true}}, "news_metadata": {"publisher": "Коммерсантъ", "source_id": "kommersant", "limitations": ["Extracted public body; completeness and source claims are not independently verified."], "collected_at": "2026-10-21T19:59:58.568791Z", "date_provenance": "h